(127800, 6062, 156, '<td valign="top">nice light, very serene, i like!</td>', 'nice light, very serene, i like!', '2002-09-23 19:50:00.000000', NULL, 1),
(127801, 6062, 2553, '<td valign="top">Love your window !  This bathroom looks very spartan, but the photo projects a soft quiet beauty in it''s diffused shadows, and the glow from the window.  I like it.  lhall-8</td>', 'Love your window !  This bathroom looks very spartan, but the photo projects a soft quiet beauty in it''s diffused shadows, and the glow from the window.  I like it.  lhall-8', '2002-09-24 06:43:00.000000', NULL, 1),
