(128638, 6143, 1543, '<td valign="top">like the b&amp;w.</td>', 'like the b&w.', '2002-09-26 15:55:00.000000', NULL, 1),
(128639, 6143, 806, '<td valign="top">suggestion: a white sheet infront of the TV would eliminate it''s refection in the mirror. Soft focus is an interesting touch.</td>', 'suggestion: a white sheet infront of the TV would eliminate it''s refection in the mirror. Soft focus is an interesting touch.', '2002-09-26 21:33:00.000000', NULL, 1),
(128640, 6143, 4057, '<td valign="top">A 1 cuz you may be lazy,a 5 for the layout,a -2 for being out of focus and -4 because I just don''t get it.....wait,that''s 0...oh well,2 for trying???...no,maybe 3,wait a sec...I see it now......it''s a 1,cuz.....I got totally lost in ''your corner of the world''.It looks like a scanned B&amp;B brochure...sorry.I don''t mean to offend...that''s only my opinion---others may see it differently.</td>', 'A 1 cuz you may be lazy,a 5 for the layout,a -2 for being out of focus and -4 because I just don''t get it.....wait,that''s 0...oh well,2 for trying???...no,maybe 3,wait a sec...I see it now......it''s a 1,cuz.....I got totally lost in ''your corner of the world''.It looks like a scanned B&B brochure...sorry.I don''t mean to offend...that''s only my opinion---others may see it differently.', '2002-09-26 21:59:00.000000', NULL, 1),
(128641, 6143, 2009, '<td valign="top">VERY interesting place for a mirror. :D</td>', 'VERY interesting place for a mirror. :D', '2002-09-27 16:10:00.000000', NULL, 1),
