(130013, 6241, 3102, '<td valign="top">Nice &amp; crisp!</td>', 'Nice & crisp!', '2002-09-23 01:43:00.000000', NULL, 1),
(130014, 6241, 3280, '<td valign="top">Great focus, you can almost count the feathers!</td>', 'Great focus, you can almost count the feathers!', '2002-09-23 07:34:00.000000', NULL, 1),
(130015, 6241, 3540, '<td valign="top">Good closeup of this bird!!  I like that the backdrop is pretty much empty.</td>', 'Good closeup of this bird!!  I like that the backdrop is pretty much empty.', '2002-09-23 12:36:00.000000', NULL, 1),
(130016, 6241, 327, '<td valign="top">Nicely done Gull. Score 8 Justine</td>', 'Nicely done Gull. Score 8 Justine', '2002-09-23 12:45:00.000000', NULL, 1),
